import type { WixDataSearchOptions } from './types'

/**
 * Options builder for search operations.
 *
 * Use this builder to configure search behavior such as translation language
 * and reference inclusion.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataSearchOptionsBuilder {
  /**
   * Sets the language used for the search.
   */
  withLanguage(value: string): WixDataSearchOptionsBuilder
  /**
   * Includes referenced items for the specified reference fields.
   *
   * Use `limit` to cap how many referenced items each field returns.
   */
  withIncludeReferences(
    value: { field: string; limit?: number }[]
  ): WixDataSearchOptionsBuilder
  /**
   * Builds the search options object.
   */
  build(): WixDataSearchOptions
}

class WixDataSearchOptionsBuilderImpl implements WixDataSearchOptionsBuilder {
  constructor(private readonly options: WixDataSearchOptions = {}) {}

  withLanguage(value: string): WixDataSearchOptionsBuilder {
    return this.copy({ language: value })
  }

  withIncludeReferences(
    value: { field: string; limit?: number }[]
  ): WixDataSearchOptionsBuilder {
    return this.copy({
      includeReferences: value.map((includeReference) => ({
        ...includeReference,
      })),
    })
  }

  build(): WixDataSearchOptions {
    return {
      ...this.options,
      ...(this.options.includeReferences
        ? {
            includeReferences: this.options.includeReferences.map(
              (includeReference) => ({ ...includeReference })
            ),
          }
        : {}),
    }
  }

  private copy(options: WixDataSearchOptions): WixDataSearchOptionsBuilder {
    return new WixDataSearchOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new search options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a search options builder"
 * import { items, SearchBuilder, SearchOptionsBuilder, SearchParams } from '@wix/data'
 *
 * const searchRequest = SearchBuilder()
 *   .withSearch(SearchParams.expression('red car'))
 *   .build()
 *
 * const options = SearchOptionsBuilder()
 *   .withIncludeReferences([{ field: 'author', limit: 3 }])
 *   .build()
 *
 * const result = await items.search<MyItem>(
 *   'myCollection',
 *   searchRequest,
 *   options
 * )
 * ```
 */
export const SearchOptionsBuilder: () => WixDataSearchOptionsBuilder = () =>
  new WixDataSearchOptionsBuilderImpl()
